-- PolicyTwin schema v2 (generated by `npm run db:schema` from src/lib/store/tables.ts — do not edit by hand)
CREATE TABLE IF NOT EXISTS policies (
  seq SERIAL,
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  description TEXT NOT NULL,
  created_by TEXT NOT NULL,
  owner_session TEXT NOT NULL,
  created_at TIMESTAMPTZ NOT NULL,
  intake_json JSONB NOT NULL
);

CREATE TABLE IF NOT EXISTS policy_versions (
  seq SERIAL,
  id TEXT PRIMARY KEY,
  policy_id TEXT NOT NULL,
  version INTEGER NOT NULL,
  label TEXT NOT NULL,
  source_text TEXT NOT NULL,
  structured_policy_json JSONB,
  analysis_json JSONB,
  status TEXT NOT NULL,
  created_at TIMESTAMPTZ NOT NULL,
  CONSTRAINT policy_versions_label_check CHECK (label IN ('A', 'B', 'C')),
  CONSTRAINT policy_versions_status_check CHECK (status IN ('current', 'proposed', 'repair_proposed', 'repair_approved')),
  CONSTRAINT policy_versions_policy_id_version_key UNIQUE (policy_id, version),
  CONSTRAINT policy_versions_policy_id_fkey FOREIGN KEY (policy_id) REFERENCES policies (id)
);

CREATE TABLE IF NOT EXISTS test_runs (
  seq SERIAL,
  id TEXT PRIMARY KEY,
  policy_id TEXT NOT NULL,
  policy_version_a TEXT NOT NULL,
  policy_version_b TEXT NOT NULL,
  parent_run_id TEXT,
  status TEXT NOT NULL,
  stage TEXT NOT NULL,
  rev INTEGER NOT NULL,
  locked_until TIMESTAMPTZ,
  failed_stage TEXT,
  last_error TEXT,
  release_decision TEXT,
  started_at TIMESTAMPTZ NOT NULL,
  completed_at TIMESTAMPTZ,
  created_by TEXT NOT NULL,
  owner_session TEXT NOT NULL,
  options_json JSONB NOT NULL,
  report_json JSONB,
  CONSTRAINT test_runs_status_check CHECK (status IN ('created', 'twins_generated', 'evaluated', 'completed', 'failed')),
  CONSTRAINT test_runs_stage_check CHECK (stage IN ('CREATED', 'GENERATING', 'TWINS_READY', 'EVALUATING', 'EVALUATED', 'EXECUTING', 'COMPLETED', 'DECIDED')),
  CONSTRAINT test_runs_release_decision_check CHECK (release_decision IS NULL OR release_decision IN ('PASS', 'REVIEW', 'BLOCK')),
  CONSTRAINT test_runs_parent_run_id_key UNIQUE (parent_run_id),
  CONSTRAINT test_runs_policy_id_fkey FOREIGN KEY (policy_id) REFERENCES policies (id),
  CONSTRAINT test_runs_policy_version_a_fkey FOREIGN KEY (policy_version_a) REFERENCES policy_versions (id),
  CONSTRAINT test_runs_policy_version_b_fkey FOREIGN KEY (policy_version_b) REFERENCES policy_versions (id),
  CONSTRAINT test_runs_parent_run_id_fkey FOREIGN KEY (parent_run_id) REFERENCES test_runs (id)
);

CREATE TABLE IF NOT EXISTS run_stages (
  seq SERIAL,
  id TEXT PRIMARY KEY,
  run_id TEXT NOT NULL,
  stage_name TEXT NOT NULL,
  status TEXT NOT NULL,
  attempts INTEGER NOT NULL,
  started_at TIMESTAMPTZ NOT NULL,
  finished_at TIMESTAMPTZ,
  locked_until TIMESTAMPTZ,
  last_error TEXT,
  CONSTRAINT run_stages_status_check CHECK (status IN ('RUNNING', 'DONE', 'FAILED')),
  CONSTRAINT run_stages_run_id_stage_name_key UNIQUE (run_id, stage_name),
  CONSTRAINT run_stages_run_id_fkey FOREIGN KEY (run_id) REFERENCES test_runs (id)
);

CREATE TABLE IF NOT EXISTS scenarios (
  seq SERIAL,
  id TEXT PRIMARY KEY,
  test_run_id TEXT NOT NULL,
  pair_id TEXT NOT NULL,
  scenario_type TEXT NOT NULL,
  scenario_key TEXT NOT NULL,
  input_json JSONB NOT NULL,
  changed_field TEXT NOT NULL,
  expected_behavior TEXT NOT NULL,
  meta_json JSONB NOT NULL,
  CONSTRAINT scenarios_scenario_type_check CHECK (scenario_type IN ('base', 'twin')),
  CONSTRAINT scenarios_expected_behavior_check CHECK (expected_behavior IN ('must_differ', 'must_match')),
  CONSTRAINT scenarios_test_run_id_scenario_key_key UNIQUE (test_run_id, scenario_key),
  CONSTRAINT scenarios_test_run_id_fkey FOREIGN KEY (test_run_id) REFERENCES test_runs (id)
);

CREATE TABLE IF NOT EXISTS policy_decisions (
  seq SERIAL,
  id TEXT PRIMARY KEY,
  test_run_id TEXT NOT NULL,
  scenario_id TEXT NOT NULL,
  policy_version TEXT NOT NULL,
  decision TEXT NOT NULL,
  reason_codes JSONB NOT NULL,
  explanation TEXT NOT NULL,
  detail_json JSONB NOT NULL,
  CONSTRAINT policy_decisions_policy_version_check CHECK (policy_version IN ('A', 'B', 'C')),
  CONSTRAINT policy_decisions_decision_check CHECK (decision IN ('AUTO_REFUND', 'REVIEW')),
  CONSTRAINT policy_decisions_scenario_id_policy_version_key UNIQUE (scenario_id, policy_version),
  CONSTRAINT policy_decisions_test_run_id_fkey FOREIGN KEY (test_run_id) REFERENCES test_runs (id),
  CONSTRAINT policy_decisions_scenario_id_fkey FOREIGN KEY (scenario_id) REFERENCES scenarios (id)
);

CREATE TABLE IF NOT EXISTS paypal_executions (
  seq SERIAL,
  id TEXT PRIMARY KEY,
  test_run_id TEXT NOT NULL,
  scenario_id TEXT NOT NULL,
  policy_version TEXT NOT NULL,
  operation TEXT NOT NULL,
  request_id TEXT,
  logical_request_id TEXT,
  paypal_order_id TEXT,
  paypal_capture_id TEXT,
  paypal_refund_id TEXT,
  status TEXT NOT NULL,
  http_status INTEGER,
  mode TEXT NOT NULL,
  lane TEXT NOT NULL,
  request_json JSONB,
  response_json JSONB,
  note TEXT,
  CONSTRAINT paypal_executions_policy_version_check CHECK (policy_version IN ('A', 'B', 'C')),
  CONSTRAINT paypal_executions_status_check CHECK (status IN ('SUCCESS', 'FAILED', 'REPLAYED', 'SKIPPED', 'INFO')),
  CONSTRAINT paypal_executions_mode_check CHECK (mode IN ('simulated', 'sandbox')),
  CONSTRAINT paypal_executions_lane_check CHECK (lane IN ('shadow', 'sandbox_proof')),
  CONSTRAINT paypal_executions_test_run_id_fkey FOREIGN KEY (test_run_id) REFERENCES test_runs (id),
  CONSTRAINT paypal_executions_scenario_id_fkey FOREIGN KEY (scenario_id) REFERENCES scenarios (id)
);

CREATE TABLE IF NOT EXISTS invariant_results (
  seq SERIAL,
  id TEXT PRIMARY KEY,
  test_run_id TEXT NOT NULL,
  scenario_id TEXT NOT NULL,
  policy_version TEXT NOT NULL,
  invariant_code TEXT NOT NULL,
  lane TEXT NOT NULL,
  passed BOOLEAN NOT NULL,
  severity TEXT NOT NULL,
  evidence_json JSONB NOT NULL,
  CONSTRAINT invariant_results_policy_version_check CHECK (policy_version IN ('A', 'B', 'C')),
  CONSTRAINT invariant_results_severity_check CHECK (severity IN ('critical')),
  CONSTRAINT invariant_results_lane_check CHECK (lane IN ('shadow', 'sandbox_proof')),
  CONSTRAINT invariant_results_scenario_id_policy_version_invariant_code_lane_key UNIQUE (scenario_id, policy_version, invariant_code, lane),
  CONSTRAINT invariant_results_test_run_id_fkey FOREIGN KEY (test_run_id) REFERENCES test_runs (id),
  CONSTRAINT invariant_results_scenario_id_fkey FOREIGN KEY (scenario_id) REFERENCES scenarios (id)
);

CREATE TABLE IF NOT EXISTS agent_runs (
  seq SERIAL,
  id TEXT PRIMARY KEY,
  test_run_id TEXT,
  agent_name TEXT NOT NULL,
  input_hash TEXT NOT NULL,
  model TEXT NOT NULL,
  structured_output JSONB,
  status TEXT NOT NULL,
  notes_json JSONB NOT NULL,
  created_at TIMESTAMPTZ NOT NULL,
  CONSTRAINT agent_runs_test_run_id_fkey FOREIGN KEY (test_run_id) REFERENCES test_runs (id)
);

CREATE TABLE IF NOT EXISTS audit_events (
  seq SERIAL,
  id TEXT PRIMARY KEY,
  test_run_id TEXT,
  event_type TEXT NOT NULL,
  actor TEXT NOT NULL,
  payload_hash TEXT NOT NULL,
  payload_json JSONB,
  created_at TIMESTAMPTZ NOT NULL,
  CONSTRAINT audit_events_test_run_id_fkey FOREIGN KEY (test_run_id) REFERENCES test_runs (id)
);

CREATE TABLE IF NOT EXISTS webhook_events (
  seq SERIAL,
  id TEXT PRIMARY KEY,
  event_type TEXT NOT NULL,
  resource_id TEXT,
  status TEXT NOT NULL,
  attempts INTEGER NOT NULL,
  last_error TEXT,
  next_attempt_at TIMESTAMPTZ,
  locked_until TIMESTAMPTZ,
  received_at TIMESTAMPTZ NOT NULL,
  verified_at TIMESTAMPTZ,
  processed_at TIMESTAMPTZ,
  payload_json JSONB,
  CONSTRAINT webhook_events_status_check CHECK (status IN ('RECEIVED', 'VERIFIED', 'PROCESSING', 'PROCESSED', 'FAILED_RETRYABLE', 'FAILED_PERMANENT'))
);

CREATE TABLE IF NOT EXISTS resource_states (
  seq SERIAL,
  id TEXT PRIMARY KEY,
  status TEXT NOT NULL,
  as_of TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS jobs (
  seq SERIAL,
  id TEXT PRIMARY KEY,
  kind TEXT NOT NULL,
  dedupe_key TEXT NOT NULL,
  payload_json JSONB NOT NULL,
  status TEXT NOT NULL,
  attempts INTEGER NOT NULL,
  max_attempts INTEGER NOT NULL,
  run_at TIMESTAMPTZ NOT NULL,
  locked_until TIMESTAMPTZ,
  last_error TEXT,
  created_at TIMESTAMPTZ NOT NULL,
  updated_at TIMESTAMPTZ NOT NULL,
  CONSTRAINT jobs_status_check CHECK (status IN ('QUEUED', 'RUNNING', 'DONE', 'FAILED')),
  CONSTRAINT jobs_dedupe_key_key UNIQUE (dedupe_key)
);

CREATE INDEX IF NOT EXISTS idx_policies_owner ON policies (owner_session);

CREATE INDEX IF NOT EXISTS idx_runs_owner ON test_runs (owner_session);

CREATE INDEX IF NOT EXISTS idx_runs_policy ON test_runs (policy_id);

CREATE INDEX IF NOT EXISTS idx_versions_policy ON policy_versions (policy_id);

CREATE INDEX IF NOT EXISTS idx_scenarios_run ON scenarios (test_run_id);

CREATE INDEX IF NOT EXISTS idx_decisions_run ON policy_decisions (test_run_id);

CREATE INDEX IF NOT EXISTS idx_exec_run ON paypal_executions (test_run_id);

CREATE INDEX IF NOT EXISTS idx_inv_run ON invariant_results (test_run_id);

CREATE INDEX IF NOT EXISTS idx_audit_run ON audit_events (test_run_id);

CREATE INDEX IF NOT EXISTS idx_agent_created ON agent_runs (created_at);

CREATE INDEX IF NOT EXISTS idx_jobs_due ON jobs (status, run_at);

CREATE INDEX IF NOT EXISTS idx_webhooks_status ON webhook_events (status);
